int mlx4_register_vlan(struct mlx4_dev *dev, u8 port, u16 vlan, int *index)
{
	int err = -ENOSPC;
	int i;

	mutex_lock(&dev->port[port].vlan_table_mutex);

	for (i = 0; i < MLX4_MAX_VLAN_ENTRIES; ++i) {
		struct mlx4_vlan_entry *entry = &dev->port[port].vlan_table[i];

		if (entry->vlan == vlan) {
			/* VLAN already registered, increment reference count */
			entry->ref_count++;
			*index = i;
			err = 0;
			goto out;
		}
	}

	/* No existing entry found, check for available space */
	for (i = 0; i < MLX4_MAX_VLAN_ENTRIES; ++i) {
		struct mlx4_vlan_entry *entry = &dev->port[port].vlan_table[i];

		if (entry->ref_count == 0) {
			entry->vlan = vlan;
			entry->ref_count = 1;
			*index = i;
			err = 0;
			break;
		}
	}

out:
	mutex_unlock(&dev->port[port].vlan_table_mutex);
	return err;
}

int mlx4_register_vlan(struct mlx4_dev *dev, u8 port, u16 vlan, int *index)
{
	int err = 0;
	int i;
	struct mlx4_vlan_table *vlan_table;

	mutex_lock(&dev->port[port - 1].vlan_table_mutex);
	vlan_table = &dev->port[port - 1].vlan_table;

	for (i = 0; i < MLX4_MAX_VLAN_ENTRIES; ++i) {
		if (vlan_table->vlan[i] == vlan) {
			vlan_table->ref_count[i]++;
			*index = i;
			goto unlock;
		}
	}

	for (i = 0; i < MLX4_MAX_VLAN_ENTRIES; ++i) {
		if (vlan_table->ref_count[i] == 0) {
			vlan_table->vlan[i] = vlan;
			vlan_table->ref_count[i] = 1;
			*index = i;
			goto unlock;
		}
	}

	err = -ENOSPC;
unlock:
	mutex_unlock(&dev->port[port - 1].vlan_table_mutex);
	return err;
}

int register_vlan(struct mlx4_dev *dev, u8 port, u16 vlan, int *index) {
    int err = -ENOSPC;
    struct mlx4_vlan_entry *vlan_table;
    int num_vlans;
    int i;

    mutex_lock(&dev->vlan_mutex);

    vlan_table = dev->vlan_table[port];
    num_vlans = dev->num_vlans[port];

    for (i = 0; i < num_vlans; ++i) {
        if (vlan_table[i].vlan == vlan) {
            ++vlan_table[i].refcnt;
            *index = i;
            err = 0;
            goto out;
        }
    }

    for (i = 0; i < num_vlans; ++i) {
        if (!vlan_table[i].vlan) {
            vlan_table[i].vlan = vlan;
            vlan_table[i].refcnt = 1;
            *index = i;
            err = 0;
            break;
        }
    }

out:
    mutex_unlock(&dev->vlan_mutex);
    return err;
}

int mlx4_register_vlan(struct mlx4_dev *dev, u8 port, u16 vlan, int *index)
{
	int err = -ENOSPC;
	int i;

	mutex_lock(&dev->vlan_table.mutex);
	for (i = 0; i < MLX4_MAX_VLAN_ENTRIES; ++i) {
		if (dev->vlan_table.table[i].vlan == vlan &&
		    dev->vlan_table.table[i].port == port) {
			/* VLAN already registered, increment reference count */
			dev->vlan_table.table[i].ref_count++;
			*index = i;
			err = 0;
			goto out;
		}
	}

	/* Find an empty slot */
	for (i = 0; i < MLX4_MAX_VLAN_ENTRIES; ++i) {
		if (dev->vlan_table.table[i].ref_count == 0) {
			dev->vlan_table.table[i].vlan = vlan;
			dev->vlan_table.table[i].port = port;
			dev->vlan_table.table[i].ref_count = 1;
			*index = i;
			err = 0;
			goto out;
		}
	}

out:
	mutex_unlock(&dev->vlan_table.mutex);
	return err;
}
